//! 🧪️ Full pin and role intents preserve their exact inverse and close every denied or cancelled native prefix.
use super::*;
#[path="../../../../📸️snapshot/🧳️state/🧪️tests/🧰️helpers/🦀️.rs"]mod helpers;
use helpers::{source,grant,observe,drain,central_fragment,project_record};
fn fixture<T:semio_framework_value::FromValue>(value:&serde_json::Value)->T{T::from_value(helpers::wire(value)).unwrap()}
#[derive(semio_framework_value::RetireOwned)]struct Payload{link:Option<ArtifactLink>}
std::thread_local!{static DESIRED_PROJECTIONS:std::cell::Cell<usize>=const{std::cell::Cell::new(0)};}
fn count_desired(){DESIRED_PROJECTIONS.with(|n|n.set(n.get()+1));}
struct Weather;struct Referenced;
impl RootLinkPath<Payload> for Weather{const SLOT:RootLinkSlot=RootLinkSlot::Weather;const DESIRED_WORK:u64=3;fn desired(p:RetainedCloneRef<'_,Payload>)->Option<RetainedCloneRef<'_,ArtifactLink>>{count_desired();p.get().link.as_ref()?;Some(p.project(0,|p|p.link.as_ref().unwrap()))}}
impl RootLinkPath<Payload> for Referenced{const SLOT:RootLinkSlot=RootLinkSlot::ReferencedModel;const DESIRED_WORK:u64=3;fn desired(p:RetainedCloneRef<'_,Payload>)->Option<RetainedCloneRef<'_,ArtifactLink>>{count_desired();p.get().link.as_ref()?;Some(p.project(0,|p|p.link.as_ref().unwrap()))}}
fn denied(g:RetainedCloneGrant,d:RetirementDemand)->Vec<RetainedCloneGrant>{let mut values=vec![RetainedCloneGrant{maximum_items:0,..g}];if d.copy_bytes>0{values.push(RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g})}if d.capacity_bytes>0{values.push(RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..g})}if d.release_bytes>0{values.push(RetainedCloneGrant{maximum_release_bytes:d.release_bytes-1,..g})}if d.depth>0{values.push(RetainedCloneGrant{maximum_depth:d.depth-1,..g})}values}
fn run<S:RootLinkPath<Payload>>(case:&serde_json::Value,law:&serde_json::Value){let body=law["bodyBytes"].as_u64().unwrap()as usize;let work=law["ownerWorkUnits"].as_u64().unwrap();let mut document:serde_json::Value=serde_json::from_str(include_str!("../../../../📸️snapshot/🧬️original/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let mut document=document["document"].take();document["model"]=helpers::corpus()["model"].clone();let field=match S::SLOT{RootLinkSlot::Weather=>"weatherLink",RootLinkSlot::ReferencedModel=>"referencedModel"};document[field]=case["before"].clone();let original=source(fixture::<EnergyModelSnapshot>(&document));let foreign_original=source(fixture::<EnergyModelSnapshot>(&document));let foreign_payload=source(Payload{link:None});let payload=source(Payload{link:if case["value"].is_null(){None}else{Some(fixture::<ArtifactLink>(&case["value"]))}});
 for cutoff in std::iter::once(None).chain(law["cancelAt"].as_array().unwrap().iter().map(|n|Some(n.as_u64().unwrap()as usize))){let mut owner=RootLinkPreparation::<S,Payload>::new();let mut turns=0;while !owner.ready()&&cutoff.is_none_or(|cut|turns<cut){if turns>0{let(r,h)=observe(||owner.demand(foreign_payload.borrow(),None,original.borrow(),body,work));assert!(r.is_err());assert_eq!(h,(0,0));}if turns>1{let(r,h)=observe(||owner.demand(payload.borrow(),None,foreign_original.borrow(),body,work));assert!(r.is_err());assert_eq!(h,(0,0));}let d=owner.demand(payload.borrow(),None,original.borrow(),body,work).unwrap();assert!(d.copy_bytes<=body&&d.capacity_bytes<=law["capacityBytes"].as_u64().unwrap()as usize,"{} native root birth exceeds original copy/capacity policy: {d:?}",case["id"]);let g=grant(d);for g in denied(g,d){let before=DESIRED_PROJECTIONS.with(|n|n.get());let(turn,h)=observe(||owner.advance(payload.borrow(),None,original.borrow(),body,work,g));let selected=DESIRED_PROJECTIONS.with(|n|n.get()-before);if law["checkOwnerPartialDenialWork"].as_bool().unwrap(){assert!(turn.work>=selected as u64*S::DESIRED_WORK);}let s=turn.result.unwrap();assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(owner.demand(payload.borrow(),None,original.borrow(),body,work).unwrap(),d);}let quoted=owner.work_demand(payload.borrow(),None,original.borrow(),body,work).unwrap();let denied=owner.advance(payload.borrow(),None,original.borrow(),body,0,g);assert_eq!(denied.work,0);assert_eq!(denied.result.unwrap().progress(),Default::default());let(turn,h)=observe(||owner.advance(payload.borrow(),None,original.borrow(),body,work,g));assert!(turn.work>0&&turn.work<=quoted);let s=turn.result.unwrap();assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));assert!(s.progress().fits(g));turns+=1;assert!(turns<100000,"{} native root did not decide",case["id"]);}
 if cutoff.is_none(){let outcome=owner.outcome().unwrap();assert_eq!(outcome.as_str(),case["outcome"].as_str().unwrap());if outcome==RowOutcome::Changed{let(diff,_)=owner.take(grant(owner.take_demand().unwrap())).unwrap().unwrap();let diff=source(diff);let mut post=project_record(original.borrow());assert!(central_fragment(&diff,original.borrow(),&mut post));let after=match S::SLOT{RootLinkSlot::Weather=>post.weather_link.get(),RootLinkSlot::ReferencedModel=>post.referenced_model.get()};let expected=if case["after"].is_null(){None}else{Some(fixture::<ArtifactLink>(&case["after"]))};assert_eq!(after,&expected);drain(expected);assert_eq!(post.model.geometry.identity(),original.borrow().get().model.geometry.identity());let(value,_)=owner.take_inverse(grant(owner.take_inverse_demand().unwrap())).unwrap().unwrap();assert_eq!(value.as_ref(),S::SLOT.source(original.borrow()).get().as_ref());drain(value);drain(post);drain(diff);}}
 owner.begin_close();for index in 0..100000{if owner.terminal_is_empty(){break}let d=owner.close_demand(body).unwrap();assert!(d.copy_bytes<=body&&d.capacity_bytes<=law["capacityBytes"].as_u64().unwrap()as usize,"native original close quote {d:?}");let g=grant(d);for g in denied(g,d){let(s,h)=observe(||owner.close_step(g).result.unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(owner.close_demand(body).unwrap(),d);}let quoted=owner.close_work_demand(body).unwrap();let(turn,h)=observe(||owner.close_step(g));assert!(turn.work>0&&turn.work<=quoted);let s=turn.result.unwrap();assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));assert!(index<99999,"native root close did not finish at {d:?}");}assert!(owner.terminal_is_empty());assert_eq!(observe(||drop(owner)).1,(0,0));
 }drain(payload);drain(foreign_payload);drain(foreign_original);drain(original);
}
#[test]fn original_root_links_preserve_complete_pin_role_and_sparse_inverse_across_all_denied_and_cancelled_prefixes(){let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for case in law["cases"].as_array().unwrap(){if case["slot"]=="weather_link"{run::<Weather>(case,&law)}else{run::<Referenced>(case,&law)}}}
#[test]fn root_link_equality_respects_work_budget_and_neutral_link_cases(){let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for case in law["cases"].as_array().unwrap(){if case["before"].is_null()||case["value"].is_null(){continue}let left=<ArtifactLink as semio_framework_value::FromValue>::from_value(helpers::wire(&case["before"])).unwrap();let right=<ArtifactLink as semio_framework_value::FromValue>::from_value(helpers::wire(&case["value"])).unwrap();let mut cursor=RootLinkEquality::new();let mut turns=0;while cursor.result().is_none(){let body=law["bodyBytes"].as_u64().unwrap()as usize;let work=law["comparisonWorkUnits"].as_u64().unwrap();let d=cursor.demand(&left,&right,body,work).unwrap();let g=grant(d);if law["checkZeroBodyDenial"].as_bool().unwrap(){let denied=cursor.advance(&left,&right,0,work,g);assert_eq!(denied.work,0);assert_eq!(denied.result.unwrap().progress(),Default::default());assert!(cursor.result().is_none());}let denied=cursor.advance(&left,&right,body,0,g);assert_eq!(denied.work,0);assert_eq!(denied.result.unwrap().progress(),Default::default());let quoted=cursor.work_demand(&left,&right,body,work).unwrap();if law["checkPinInspectionWork"].as_bool().unwrap()&&cursor.selection_work()==0{let partial=cursor.advance(&left,&right,body,1,g);assert_eq!(partial.work,1);assert_eq!(partial.result.unwrap().progress(),Default::default());assert!(cursor.result().is_none());}if law["checkDeniedProjectionWork"].as_bool().unwrap()&&cursor.selection_work()>0&&d.copy_bytes>3{let denied=cursor.advance(&left,&right,body,work,RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g});assert!(denied.work>0&&denied.work<=quoted);assert_eq!(denied.result.unwrap().progress(),Default::default());assert!(cursor.result().is_none());}let turn=cursor.advance(&left,&right,body,work,g);assert!(turn.work>0&&turn.work<=quoted);assert!(turn.result.unwrap().progress().fits(g));turns+=1;assert!(turns<100000)}assert_eq!(cursor.result(),Some(case["before"]==case["value"]));drain(left);drain(right);}}
